+trait PermissionSnapshotSource {
+    fn revision(&self) -> u64;
+    fn fetch<'a>(&'a mut self) -> LocalBoxFuture<'a, Result<Vec<PendingPermission>, String>>;
+    fn apply(&mut self, snapshot: Vec<PendingPermission>);
