+        && sources.lifecycle.ready()
+        && sources
+            .agent
+            .as_ref()
+            .is_some_and(|source| source.state() == EventSourceState::Open)
+        && sources
+            .permission
+            .as_ref()
+            .is_some_and(|source| source.state() == EventSourceState::Open)
