   790	    // preserving browser/PWA Print and Find. Cmd/Ctrl+K closes the Island before
   791	    // PaletteView handles the same event.
   792	    let _island_shortcut = window_event_listener(ev::keydown, move |e: ev::KeyboardEvent| {
   793	        if e.is_composing() {
   794	            return;
   795	        }
   796	        let command = e.meta_key() || e.ctrl_key();
   797	        if command
   798	            && !e.shift_key()
   799	            && !e.alt_key()
   800	            && e.key().eq_ignore_ascii_case("k")
   801	            && island_mode.get_untracked() != IslandMode::Closed
   802	        {
   803	            island_mode.set(IslandMode::Closed);
   804	        }
   805	        if in_tauri
   806	            && command
   807	            && !e.shift_key()
   808	            && !e.alt_key()
   809	            && e.key().eq_ignore_ascii_case("p")
   810	        {
   811	            e.prevent_default();
   812	            e.stop_propagation();
   813	            open_island.run(IslandMode::Sessions);
   814	        } else if in_tauri
