    35	// Browsers cap concurrent HTTP/1.1 connections per origin. Each focused
    36	// session owns two long-lived EventSource requests (agent events + permission
    37	// events), so merely generation-gating stale readers is not enough: an idle
    38	// stale stream never yields another frame, remains open, and eventually blocks
    39	// the snapshot request for a later session. Keep explicit handles so every
    40	// focus change can close both transports before opening their replacements.
    41	#[cfg(target_arch = "wasm32")]
    42	type EventSourceSlot = Arc<Mutex<Option<SendWrapper<EventSource>>>>;
    43	
    44	#[cfg(target_arch = "wasm32")]
    45	fn replace_event_source(slot: &EventSourceSlot, next: EventSource) {
    46	    let previous = slot
    47	        .lock()
    48	        .expect("event source slot poisoned")
    49	        .replace(SendWrapper::new(next));
    50	    if let Some(previous) = previous {
    51	        previous.take().close();
    52	    }
    53	}
